{
  "name": "temperature-converter",
  "version": "1.0.0",
  "description": "Browser-based temperature converter",
  "type": "module",
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "start": "node src/server.js",
    "build": "node --check src/convert.js && node --check src/app.js && node --check src/server.js",
    "test": "node --test"
  }
}

import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import { convert, validate } from './convert.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const INDEX_PATH = join(__dirname, '..', 'public', 'index.html');

function sendJson(res, statusCode, body) {
  const payload = JSON.stringify(body);
  res.writeHead(statusCode, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(payload)
  });
  res.end(payload);
}

async function readJsonBody(req) {
  const chunks = [];
  for await (const chunk of req) {
    chunks.push(chunk);
  }
  const raw = Buffer.concat(chunks).toString('utf8');
  return JSON.parse(raw);
}

function route(req, res) {
  const url = new URL(req.url, 'http://localhost');
  const { pathname } = url;

  if (req.method === 'GET' && pathname === '/') {
    return serveIndex(res);
  }

  if (req.method === 'GET' && pathname === '/health') {
    return sendJson(res, 200, { status: 'ok' });
  }

  if (req.method === 'POST' && pathname === '/api/convert') {
    return handleConvert(req, res);
  }

  sendJson(res, 404, { error: 'Not found' });
}

async function serveIndex(res) {
  try {
    const html = await readFile(INDEX_PATH, 'utf8');
    res.writeHead(200, {
      'Content-Type': 'text/html; charset=utf-8',
      'Content-Length': Buffer.byteLength(html)
    });
    res.end(html);
  } catch {
    sendJson(res, 500, { error: 'Unable to serve index' });
  }
}

async function handleConvert(req, res) {
  let payload;
  try {
    payload = await readJsonBody(req);
  } catch {
    sendJson(res, 400, { error: 'Malformed JSON' });
    return;
  }

  try {
    const { value, from, to } = validate(payload);
    const result = convert(value, from, to);
    sendJson(res, 200, result);
  } catch (err) {
    const message = err && err.message ? err.message : 'Invalid request';
    sendJson(res, 400, { error: message });
  }
}

/**
 * Create the HTTP server request handler.
 */
export function createApp() {
  return (req, res) => {
    route(req, res).catch(() => {
      if (!res.headersSent) {
        sendJson(res, 500, { error: 'Internal server error' });
      } else {
        res.end();
      }
    });
  };
}

const ABSOLUTE_ZERO = {
  C: -273.15,
  F: -459.67,
  K: 0
};

const SUPPORTED_UNITS = new Set(['C', 'F', 'K']);

// Insignificant floating-point error allowed at absolute-zero boundaries.
const TOLERANCE = 1e-9;

function isNumericValue(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

function isSupportedUnit(unit) {
  return typeof unit === 'string' && SUPPORTED_UNITS.has(unit);
}

/**
 * Validate a payload of {value, from, to}. Returns normalized {value, from, to}
 * or throws an Error with a nonempty message.
 */
export function validate(payload) {
  if (payload === null || typeof payload !== 'object' || Array.isArray(payload)) {
    throw new Error('Invalid request payload');
  }

  if (!('value' in payload)) {
    throw new Error('Missing required field: value');
  }
  if (!('from' in payload)) {
    throw new Error('Missing required field: from');
  }
  if (!('to' in payload)) {
    throw new Error('Missing required field: to');
  }

  const { value, from, to } = payload;

  if (!isNumericValue(value)) {
    throw new Error('Value must be a number');
  }

  if (!isSupportedUnit(from)) {
    throw new Error('Unsupported source unit');
  }
  if (!isSupportedUnit(to)) {
    throw new Error('Unsupported destination unit');
  }

  if (value < ABSOLUTE_ZERO[from] - TOLERANCE) {
    throw new Error('Temperature below absolute zero');
  }

  return { value, from, to };
}

/**
 * Convert a numeric value from one temperature unit to another.
 * Returns {value, unit}.
 */
export function convert(value, from, to) {
  const { value: v, from: f, to: t } = validate({ value, from, to });

  if (f === t) {
    return { value: v, unit: t };
  }

  // Convert source to Celsius first.
  let celsius;
  if (f === 'C') {
    celsius = v;
  } else if (f === 'F') {
    celsius = (v - 32) * 5 / 9;
  } else {
    celsius = v - 273.15;
  }

  // Convert Celsius to destination.
  let result;
  if (t === 'C') {
    result = celsius;
  } else if (t === 'F') {
    result = celsius * 9 / 5 + 32;
  } else {
    result = celsius + 273.15;
  }

  return { value: result, unit: t };
}

import { createServer } from 'node:http';

import { createApp } from './app.js';

const PORT = Number(process.env.PORT) || 3000;
const host = '0.0.0.0';

const server = createServer(createApp());

server.listen(PORT, host, () => {
  console.log(`Temperature converter listening on http://${host}:${PORT}`);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';

import { createApp } from '../src/app.js';

/**
 * Invoke the request handler with a minimal mock of the Node HTTP request
 * and response, without opening a listening server.
 */
function request(handler, { method = 'GET', url = '/', body = null } = {}) {
  return new Promise((resolve, reject) => {
    const chunks = body == null ? [] : [Buffer.from(body)];

    const req = {
      method,
      url,
      // For async iteration used by readJsonBody.
      [Symbol.asyncIterator]: async function* () {
        for (const chunk of chunks) {
          yield chunk;
        }
      }
    };

    const res = {
      statusCode: 0,
      headers: {},
      _body: Buffer.alloc(0),
      headersSent: false,
      writeHead(statusCode, headers = {}) {
        this.statusCode = statusCode;
        Object.assign(this.headers, headers);
        this.headersSent = true;
      },
      write(chunk) {
        if (!this.headersSent) this.headersSent = true;
        if (chunk) {
          this._body = Buffer.concat([this._body, Buffer.from(chunk)]);
        }
      },
      end(chunk) {
        if (chunk) {
          this._body = Buffer.concat([this._body, Buffer.from(chunk)]);
        }
        resolve({
          statusCode: this.statusCode,
          headers: this.headers,
          body: this._body.toString('utf8'),
          json() {
            return JSON.parse(this.body);
          }
        });
      }
    };

    try {
      handler(req, res);
    } catch (err) {
      reject(err);
    }
  });
}

const app = createApp;

test('GET /health returns 200 with status ok', async () => {
  const response = await request(app(), { method: 'GET', url: '/health' });
  assert.equal(response.statusCode, 200);
  assert.deepEqual(response.json(), { status: 'ok' });
});

test('GET / returns 200 with text/html', async () => {
  const response = await request(app(), { method: 'GET', url: '/' });
  assert.equal(response.statusCode, 200);
  assert.ok(
    response.headers['Content-Type'].includes('text/html'),
    `expected html content type, got ${response.headers['Content-Type']}`
  );
});

test('POST /api/convert returns 200 with converted value', async () => {
  const response = await request(app(), {
    method: 'POST',
    url: '/api/convert',
    body: JSON.stringify({ value: 100, from: 'C', to: 'F' })
  });
  assert.equal(response.statusCode, 200);
  const result = response.json();
  assert.equal(result.unit, 'F');
  assert.ok(Math.abs(result.value - 212) < 1e-9);
});

test('POST /api/convert with same unit returns 200 preserving value', async () => {
  const response = await request(app(), {
    method: 'POST',
    url: '/api/convert',
    body: JSON.stringify({ value: 50, from: 'C', to: 'C' })
  });
  assert.equal(response.statusCode, 200);
  assert.deepEqual(response.json(), { value: 50, unit: 'C' });
});

test('POST /api/convert with missing field returns 400 with error', async () => {
  const response = await request(app(), {
    method: 'POST',
    url: '/api/convert',
    body: JSON.stringify({ value: 5, from: 'C' })
  });
  assert.equal(response.statusCode, 400);
  const body = response.json();
  assert.equal(typeof body.error, 'string');
  assert.ok(body.error.length > 0);
});

test('POST /api/convert with nonnumeric value returns 400', async () => {
  const response = await request(app(), {
    method: 'POST',
    url: '/api/convert',
    body: JSON.stringify({ value: 'hot', from: 'C', to: 'F' })
  });
  assert.equal(response.statusCode, 400);
  assert.ok(response.json().error.length > 0);
});

test('POST /api/convert with boolean value returns 400', async () => {
  const response = await request(app(), {
    method: 'POST',
    url: '/api/convert',
    body: JSON.stringify({ value: true, from: 'C', to: 'F' })
  });
  assert.equal(response.statusCode, 400);
  assert.ok(response.json().error.length > 0);
});

test('POST /api/convert with unsupported unit returns 400', async () => {
  const response = await request(app(), {
    method: 'POST',
    url: '/api/convert',
    body: JSON.stringify({ value: 10, from: 'C', to: 'X' })
  });
  assert.equal(response.statusCode, 400);
  assert.ok(response.json().error.length > 0);
});

test('POST /api/convert below absolute zero returns 400', async () => {
  const response = await request(app(), {
    method: 'POST',
    url: '/api/convert',
    body: JSON.stringify({ value: -300, from: 'C', to: 'K' })
  });
  assert.equal(response.statusCode, 400);
  assert.ok(response.json().error.length > 0);
});

test('POST /api/convert with malformed JSON returns 400', async () => {
  const response = await request(app(), {
    method: 'POST',
    url: '/api/convert',
    body: '{ not valid json'
  });
  assert.equal(response.statusCode, 400);
  const body = response.json();
  assert.equal(typeof body.error, 'string');
  assert.ok(body.error.length > 0);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';

import { convert, validate } from '../src/convert.js';

const EPSILON = 1e-9;

function assertClose(actual, expected, msg) {
  assert.ok(
    Math.abs(actual - expected) < 1e-9,
    `${msg || 'values differ'}: expected ${expected}, got ${actual}`
  );
}

test('Celsius to Fahrenheit conversion uses the correct formula', () => {
  assertClose(convert(0, 'C', 'F').value, 32);
  assertClose(convert(100, 'C', 'F').value, 212);
  assertClose(convert(-40, 'C', 'F').value, -40);
  assert.equal(convert(37, 'C', 'F').unit, 'F');
});

test('Fahrenheit to Celsius conversion uses the correct formula', () => {
  assertClose(convert(32, 'F', 'C').value, 0);
  assertClose(convert(212, 'F', 'C').value, 100);
  assertClose(convert(-40, 'F', 'C').value, -40);
  assert.equal(convert(98.6, 'F', 'C').unit, 'C');
});

test('Kelvin conversions use C + 273.15 relationship', () => {
  assertClose(convert(0, 'C', 'K').value, 273.15);
  assertClose(convert(273.15, 'K', 'C').value, 0);
  assertClose(convert(0, 'K', 'C').value, -273.15);
  assertClose(convert(32, 'F', 'K').value, 273.15);
  assertClose(convert(273.15, 'K', 'F').value, 32);
});

test('conversion does not round the result to an integer', () => {
  const result = convert(0, 'F', 'C').value;
  assertClose(result, -17.77777777777778);
  assert.notEqual(result, -18);
});

test('same-unit conversion preserves the value', () => {
  assertClose(convert(25, 'C', 'C').value, 25);
  assertClose(convert(-3.5, 'F', 'F').value, -3.5);
  assertClose(convert(100, 'K', 'K').value, 100);
  assert.equal(convert(25, 'C', 'C').unit, 'C');
  assert.equal(convert(100, 'K', 'K').unit, 'K');
});

test('negative Celsius and Fahrenheit above absolute zero are valid', () => {
  assertClose(convert(-10, 'C', 'F').value, 14);
  assertClose(convert(-10, 'F', 'C').value, -23.333333333333332);
});

test('validate returns normalized value/from/to for valid payload', () => {
  assert.deepEqual(validate({ value: 10, from: 'C', to: 'F' }), {
    value: 10,
    from: 'C',
    to: 'F'
  });
});

test('validate rejects missing value field', () => {
  assert.throws(() => validate({ from: 'C', to: 'F' }), /value/);
});

test('validate rejects missing from field', () => {
  assert.throws(() => validate({ value: 0, to: 'F' }), /from/);
});

test('validate rejects missing to field', () => {
  assert.throws(() => validate({ value: 0, from: 'C' }), /to/);
});

test('validate rejects nonnumeric values', () => {
  assert.throws(() => validate({ value: '10', from: 'C', to: 'F' }), /number/i);
  assert.throws(() => validate({ value: NaN, from: 'C', to: 'F' }), /number/i);
  assert.throws(() => validate({ value: Infinity, from: 'C', to: 'F' }), /number/i);
});

test('validate rejects boolean values', () => {
  assert.throws(() => validate({ value: true, from: 'C', to: 'F' }), /number/i);
  assert.throws(() => validate({ value: false, from: 'C', to: 'F' }), /number/i);
});

test('validate rejects unsupported units', () => {
  assert.throws(() => validate({ value: 0, from: 'X', to: 'F' }), /unit/i);
  assert.throws(() => validate({ value: 0, from: 'C', to: 'X' }), /unit/i);
  assert.throws(() => validate({ value: 0, from: 'x', to: 'F' }), /unit/i);
});

test('validate rejects below absolute zero in Celsius', () => {
  assert.throws(() => validate({ value: -273.16, from: 'C', to: 'C' }), /absolute zero/i);
});

test('validate rejects below absolute zero in Fahrenheit', () => {
  assert.throws(() => validate({ value: -459.68, from: 'F', to: 'K' }), /absolute zero/i);
});

test('validate rejects below absolute zero in Kelvin', () => {
  assert.throws(() => validate({ value: -0.01, from: 'K', to: 'C' }), /absolute zero/i);
});

test('validate allows exact absolute zero boundaries', () => {
  assert.deepEqual(validate({ value: -273.15, from: 'C', to: 'F' }), {
    value: -273.15,
    from: 'C',
    to: 'F'
  });
  assert.deepEqual(validate({ value: -459.67, from: 'F', to: 'C' }), {
    value: -459.67,
    from: 'F',
    to: 'C'
  });
  assert.deepEqual(validate({ value: 0, from: 'K', to: 'C' }), {
    value: 0,
    from: 'K',
    to: 'C'
  });
});

test('validate rejects below-zero values even for same-unit conversion', () => {
  assert.throws(() => validate({ value: -273.16, from: 'C', to: 'C' }), /absolute zero/i);
  assert.throws(() => validate({ value: -0.1, from: 'K', to: 'K' }), /absolute zero/i);
});

test('validate allows insignificant floating-point error at boundaries', () => {
  // Slightly below the boundary but within tolerance.
  assert.doesNotThrow(() =>
    validate({ value: -273.15 - EPSILON, from: 'C', to: 'F' })
  );
  assert.doesNotThrow(() =>
    validate({ value: -459.67 - EPSILON, from: 'F', to: 'C' })
  );
  assert.doesNotThrow(() => validate({ value: -EPSILON, from: 'K', to: 'C' }));
});

test('validate rejects values clearly beyond the tolerance', () => {
  assert.throws(
    () => validate({ value: -273.15 - 1e-6, from: 'C', to: 'F' }),
    /absolute zero/i
  );
});

test('convert also enforces validation through validate', () => {
  assert.throws(() => convert(-300, 'C', 'K'), /absolute zero/i);
  assert.throws(() => convert('hot', 'C', 'F'), /number/i);
});
